xql_query:
// ============================================================
// Rule: AWS_IAM User creation
// Vendor: AWS
// Objective:
// Detect activity associated with AWS_IAM User creation.
// Severity: SEV_030_MEDIUM
// Category: PERSISTENCE
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1136.003 - Create Account: Cloud Account
// Technique: T1136 - Create Account

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa em campos textuais
config case_sensitive = false

// Fonte de dados: logs brutos do AWS (CloudTrail)
// O dataset 'amazon_aws_raw' contém eventos de auditoria (ex.: criação de usuários, alterações IAM, etc.)
| dataset = amazon_aws_raw

// Filtro: monitora criação de usuário IAM
// eventName = "CreateUser" indica criação de um novo usuário no IAM
| filter eventName = "CreateUser"

// Extração/normalização de campos relevantes do payload
// Observação: alguns campos podem ser objetos; por isso convertemos para string JSON antes de acessar chaves internas.
// - executor_user: identifica quem executou a ação (principalId do userIdentity)
// - user_id_created: userId do usuário IAM recém-criado dentro de responseElements.user.userId
| alter
    executor_user   = to_json_string(useridentity) -> principalId,
    user_id_created = to_json_string(responseelements) -> user.userId,
    aws_user_arn    = to_json_string(responseelements) -> user.arn


| alter
    aws_username = arrayindex(regextract(aws_user_arn, "[^/]+$"), 0)
// Seleção dos campos relevantes para auditoria e notificação do alerta
| fields
    _time,               // Timestamp do evento no XSIAM
    eventTime,           // Timestamp original do CloudTrail
    eventName,           // Nome da ação (CreateUser)
    eventSource,         // Serviço origem (ex.: iam.amazonaws.com)
    executor_user,       // Executor (principalId)
    aws_username,
    user_id_created,     // ID do usuário criado (IAM userId)
    userIdentity,        // Objeto completo do executor (evidência)
    requestParameters,   // Parâmetros da requisição (ex.: nome do usuário, path)
    responseElements,    // Resposta (detalhes do usuário criado)
    userAgent,           // User-Agent (console, SDK, CLI, etc.)
    sourceIPAddress      // IP de origem do executor

//Exception para o time de Cloud.
| filter ((`executor_user` not contains """<USER_EMAIL_1>""" and `executor_user` not contains """<USER_EMAIL_2>""" and `executor_user` not contains """<USER_EMAIL_3>"""))
| filter (eventSource != """sso-directory.amazonaws.com""")
